//! CQ11 / TK008: original entry, atomic three-Cultist cost, official token cost zero.
use crate::{engine::RuleResult,model::*,rules::*,catalog};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="CQ11";
pub(crate) const TOKEN:&str="TK008";
pub(crate) const ENTRY:&str="cq11-generate-cultist";
pub(crate) const DESTROY:&str="tk008-sacrifice-three-destroy";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Victim {pub source:SourceSnapshot,pub subtypes:Vec<String>}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn slot()->TargetSlotSpec{target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)}
pub(crate) fn definition(id:&str)->Definition{if id==ID{with_abilities(vec![ability(ENTRY,"进场：本地区生成一个邪教徒",Timing::Fast,vec![],vec![],vec![Op::CQ11Generate],Some(Event::Enter))])}else{let mut a=ability(DESTROY,"牺牲三个本方邪教徒角色：毁灭目标地区",Timing::Standard,vec![Cost::TK008SacrificeThree],vec![slot()],vec![Op::TK008Destroy],None);a.activation_only=true;with_abilities(vec![a])}}
fn owns(o:&Op)->bool{match o{Op::CQ11Generate|Op::TK008Destroy=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("cq11-")||a.key.starts_with("tk008-")||a.costs.iter().any(|c|matches!(c,Cost::TK008SacrificeThree))||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if !matches!(id,ID|TOKEN)||!same(a,&definition(id).abilities[0]){return Err("CQ11/TK008须保留原完整能力".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(matches!(id,ID|TOKEN)||d.abilities.iter().any(related))&&(!matches!(id,ID|TOKEN)||!same(d,&definition(id))){return Err("CQ11/TK008定义不可移植或删改".into());}Ok(())}
pub(crate) fn validate_action(id:&str,a:&Action)->RuleResult<()>{if !matches!(id,ID|TOKEN){return Ok(());}let expected=match a.kind.as_str(){"deploy"|"conceal" if id==ID=>Action{card_id:a.card_id.clone(),region:a.region,..Action::new(&a.kind)},"reveal"=>Action{card_id:a.card_id.clone(),..Action::new("reveal")},_=>return Err("生成物不能从手牌打出或建立资产".into())};if *a!=expected{return Err("CQ11/TK008角色动作存在多余载荷".into());}Ok(())}
fn frame_related(f:&ResolutionFrame)->bool{matches!(f.ability_key.as_str(),ENTRY|DESTROY)||f.steps.iter().any(|s|owns(&s.op))||f.already_paid.iter().any(|p|matches!(p,PaidCost::TK008Sacrificed(_)))}
impl Game {
 fn cq11_source(&self,actor:usize,s:&SourceSnapshot,id:&str)->RuleResult<()>{let c=&s.card;if c.definition!=id||actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=actor||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("CQ11/TK008来源或原地区无效".into());}self.validate_generated_identity(c)?;self.mobility_immutable_identity(c)}
 pub(crate) fn validate_cq11_declaration(&self,d:&Declaration)->RuleResult<()>{if matches!(d.source.card.definition.as_str(),ID|TOKEN)||related(&d.ability){if d.ability.key!=ENTRY{return Err("TK008没有触发声明".into());}validate_ability(&d.source.card.definition,&d.ability)?;self.cq11_source(d.actor,&d.source,ID)?;}Ok(())}
 pub(crate) fn cq11_trios(&self,actor:usize)->Vec<Vec<String>>{let ids=self.regions.iter().filter(|r|!r.vacant).flat_map(|r|&r.cards).filter(|c|c.controller==actor&&!c.face_down&&catalog::card(&c.definition).kind=="character"&&self.current_subtypes(c).iter().any(|s|s=="邪教徒")).map(|c|c.id.clone()).collect::<Vec<_>>();let mut out=vec![];for i in 0..ids.len(){for j in i+1..ids.len(){for k in j+1..ids.len(){out.push(vec![ids[i].clone(),ids[j].clone(),ids[k].clone()]);}}}out}
 pub(crate) fn cq11_pay(&mut self,actor:usize,s:&SourceSnapshot,a:&AbilitySpec,action:&Action)->RuleResult<PaidCost>{validate_ability(&s.card.definition,a)?;self.cq11_source(actor,s,TOKEN)?;if *action!=(Action{card_id:action.card_id.clone(),ability_id:Some(DESTROY.into()),region:action.region,cost_selected:action.cost_selected.clone(),..Action::new("activate")}){return Err("邪教徒仅接受原地区目标与三个牺牲费用".into());}let ids=action.cost_selected.as_ref().ok_or("缺少三邪教徒费用")?;if ids.len()!=3||ids.iter().collect::<BTreeSet<_>>().len()!=3{return Err("必须牺牲三个不同本方邪教徒角色".into());}let mut victims=vec![];for id in ids{let(r,c)=self.board(id).filter(|(_,c)|c.controller==actor&&!c.face_down&&catalog::card(&c.definition).kind=="character"&&self.current_subtypes(c).iter().any(|s|s=="邪教徒")).ok_or("牺牲对象不是本方明置邪教徒角色")?;let mut source=self.source_snapshot(c,Some(r));source.source_region_instance=Some(self.regions[r].card.id.clone());victims.push(Victim{source,subtypes:self.current_subtypes(c)});}
 let wave=victims.iter().map(|v|(v.source.card.id.clone(),RemovalCause::Sacrifice,v.source.clone())).collect();self.destroy_wave_as(actor,wave);Ok(PaidCost::TK008Sacrificed(victims))}
 pub(crate) fn validate_cq11_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if matches!(f.source.card.definition.as_str(),ID|TOKEN)&&!matches!(f.ability_key.as_str(),ENTRY|DESTROY|"deploy"|"reveal"){return Err("CQ11/TK008不能借用其他来源帧".into());}if !frame_related(f){return Ok(());}let id=if f.ability_key==ENTRY{ID}else{TOKEN};self.cq11_source(f.actor,&f.source,id)?;let a=definition(id).abilities.remove(0);if f.ability_key!=a.key||!same(&f.steps,&a.ops.iter().map(|op|Step{context:f.actor,op:op.clone()}).collect::<Vec<_>>())||!self.mystic_instance_number(&f.source.card.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!f.resource_payments.is_empty()||f.targets.len()!=a.targets.len(){return Err("CQ11/TK008结算程序、来源或阶段损坏".into());}
 if id==ID{if !f.already_paid.is_empty()||f.chosen_region.is_some(){return Err("CQ11触发不能伪造支付或地区选择".into());}}else{let t=&f.targets[0];let r=t.id.strip_prefix("region:").and_then(|s|s.parse::<usize>().ok()).filter(|r|*r<self.regions.len()).ok_or("邪教徒地区目标无效")?;if !same(&t.spec,&slot())||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||t.public.instance_id!=t.id||t.public.kind!="region"||t.public.region!=Some(r)||t.public.owner.is_some()||t.public.controller.is_some()||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some()||f.chosen_region!=Some(r){return Err("邪教徒原地区目标损坏".into());}let [PaidCost::TK008Sacrificed(v)]=f.already_paid.as_slice()else{return Err("缺少三邪教徒支付回执".into());};if v.len()!=3||v.iter().map(|v|&v.source.card.id).collect::<BTreeSet<_>>().len()!=3{return Err("邪教徒回执重复或数量不符".into());}for v in v{let c=&v.source.card;if c.controller!=f.actor||c.face_down||catalog::card(&c.definition).kind!="character"||!v.subtypes.iter().any(|s|s=="邪教徒")||v.source.region.is_none_or(|r|r>=self.regions.len())||v.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b){return Err("三邪教徒费用身份损坏".into());}self.validate_generated_identity(c)?;self.mobility_immutable_identity(c)?;}}
 Ok(())}
 pub(crate) fn cq11_step(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_cq11_frame(f)?;if f.cursor!=1{return Err("CQ11/TK008须经原结算守卫".into());}if self.players[f.actor].eliminated{return Ok(());}if f.ability_key==ENTRY{if let Some(r)=self.original_region(&f.source){let c=self.make_generated(crate::generated::GeneratedKind::Cultist,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,TOKEN,&id,false);}}else if self.valid_bound_target(f.actor,&f.source,&f.targets[0]){let r=f.chosen_region.unwrap();self.regions[r].destroyed=true;}Ok(())}
 pub(crate) fn validate_cq11_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();for i in &self.stack{self.validate_cq11_play(i)?;if let Some(f)=&i.frame{self.validate_cq11_frame(f)?;if frame_related(f)&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||f.cursor!=0||!seen.insert(&f.frame_id)){return Err("CQ11/TK008堆叠外壳或同帧重复".into());}}}for e in &self.effects{match e{Effect::Declare{declaration}=>self.validate_cq11_declaration(declaration)?,Effect::Frame{frame}if frame_related(frame)=>return Err("CQ11/TK008单步不能存在游离续体".into()),_=>{}}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,stage}=>{self.validate_cq11_declaration(d)?;if d.source.card.definition==ID{let expected=Choice{id:p.choice.id.clone(),kind:"trigger".into(),title:format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options:vec![ChoiceOption{id:"accept".into(),label:"发动触发能力".into(),card:None}],preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if !matches!(stage,DeclareChoice::Accept)||p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("CQ11可选生成待选损坏".into());}}},ChoiceResolution::Frame{frame,..}if frame_related(frame)=>return Err("CQ11/TK008没有帧内待选".into()),_=>{}}}Ok(())}
}

impl Game {
 pub(crate) fn validate_cq11_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|matches!(c.definition.as_str(),ID|TOKEN))&&!item.frame.as_ref().is_some_and(|f|matches!(f.source.card.definition.as_str(),ID|TOKEN)&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("CQ11/TK008角色事务缺少原帧")?;let c=&f.source.card;
  if !matches!(c.definition.as_str(),ID|TOKEN)||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||!matches!(f.ability_key.as_str(),"deploy"|"reveal")||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=8&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("CQ11/TK008角色事务、原帧或实际牌面不符".into());}if c.definition==TOKEN && (f.ability_key!="reveal" || f.money_units(0)!=0 || !f.resource_payments.is_empty() || !matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if ids.is_empty())) {return Err("邪教徒只接受真实零费现身事务".into());} self.validate_generated_identity(c)?;self.mobility_immutable_identity(c)
 }
}
